// Package explain renders a raw Modbus frame as bilingual human-readable
// text. Ported from crates/modbussim-app/src/frame_explain.rs; the output is
// byte-identical, which testdata/golden pins against files generated by the
// Rust implementation.
package explain

import (
	"errors"
	"fmt"
	"strings"

	"github.com/Karl-Dai/ModbusSim/go/internal/tools"
)

// Lang selects the output language.
type Lang int

const (
	// Zh is Chinese output.
	Zh Lang = iota
	// En is English output.
	En
)

// LangFromCode treats any code starting with "zh" as Chinese, like Rust's
// Lang::from_code.
func LangFromCode(code string) Lang {
	if strings.HasPrefix(code, "zh") {
		return Zh
	}
	return En
}

func (l Lang) pick(zh, en string) string {
	if l == Zh {
		return zh
	}
	return en
}

// kind groups the supported function codes by frame shape.
type kind int

const (
	kindBits kind = iota
	kindRegs
	kindWriteSingleCoil
	kindWriteSingleReg
	kindWriteMultiCoil
	kindWriteMultiReg
)

type fcInfo struct {
	zh        string
	en        string
	kind      kind
	plcBase   uint32
	unitZh    string
	unitEn    string
	unitEnPlu string
	maxQty    uint16
}

func fcInfoFor(fc byte) (fcInfo, bool) {
	switch fc {
	case 1:
		return fcInfo{zh: "读线圈", en: "Read Coils", kind: kindBits, plcBase: 0,
			unitZh: "线圈", unitEn: "coil", unitEnPlu: "coils", maxQty: 2000}, true
	case 2:
		return fcInfo{zh: "读离散输入", en: "Read Discrete Inputs", kind: kindBits, plcBase: 10000,
			unitZh: "离散输入", unitEn: "discrete input", unitEnPlu: "discrete inputs", maxQty: 2000}, true
	case 3:
		return fcInfo{zh: "读保持寄存器", en: "Read Holding Registers", kind: kindRegs, plcBase: 40000,
			unitZh: "寄存器", unitEn: "register", unitEnPlu: "registers", maxQty: 125}, true
	case 4:
		return fcInfo{zh: "读输入寄存器", en: "Read Input Registers", kind: kindRegs, plcBase: 30000,
			unitZh: "寄存器", unitEn: "register", unitEnPlu: "registers", maxQty: 125}, true
	case 5:
		return fcInfo{zh: "写单个线圈", en: "Write Single Coil", kind: kindWriteSingleCoil, plcBase: 0,
			unitZh: "线圈", unitEn: "coil", unitEnPlu: "coils"}, true
	case 6:
		return fcInfo{zh: "写单个寄存器", en: "Write Single Register", kind: kindWriteSingleReg, plcBase: 40000,
			unitZh: "寄存器", unitEn: "register", unitEnPlu: "registers"}, true
	case 15:
		return fcInfo{zh: "写多个线圈", en: "Write Multiple Coils", kind: kindWriteMultiCoil, plcBase: 0,
			unitZh: "线圈", unitEn: "coil", unitEnPlu: "coils", maxQty: 1968}, true
	case 16:
		return fcInfo{zh: "写多个寄存器", en: "Write Multiple Registers", kind: kindWriteMultiReg, plcBase: 40000,
			unitZh: "寄存器", unitEn: "register", unitEnPlu: "registers", maxQty: 123}, true
	}
	return fcInfo{}, false
}

// exceptionInfo returns the localized name and explanation of an exception
// code.
func exceptionInfo(code byte, lang Lang) (string, string, bool) {
	switch code {
	case 0x01:
		return lang.pick("非法功能", "Illegal function"),
			lang.pick("从站不认识这个功能码，可能不支持该操作",
				"the slave does not recognize this function code; the operation may not be supported"), true
	case 0x02:
		return lang.pick("非法数据地址", "Illegal data address"),
			lang.pick("要访问的寄存器在从站中不存在",
				"the register being accessed does not exist on the slave"), true
	case 0x03:
		return lang.pick("非法数据值", "Illegal data value"),
			lang.pick("请求里的数值超出了从站允许的范围",
				"the value in the request is outside the range the slave allows"), true
	case 0x04:
		return lang.pick("从站设备故障", "Slave device failure"),
			lang.pick("从站执行操作时发生内部错误",
				"an internal error occurred while the slave executed the operation"), true
	case 0x05:
		return lang.pick("确认", "Acknowledge"),
			lang.pick("从站已接受请求并正在处理，需要较长时间，可稍后再查",
				"the slave accepted the request and is processing it; this takes a while, check again later"), true
	case 0x06:
		return lang.pick("从站设备忙", "Slave device busy"),
			lang.pick("从站正在处理其他任务，请稍后重试",
				"the slave is handling other tasks; try again later"), true
	case 0x08:
		return lang.pick("存储奇偶性差错", "Memory parity error"),
			lang.pick("从站读取内部存储时校验失败",
				"the slave failed a parity check while reading its internal memory"), true
	case 0x0A:
		return lang.pick("网关路径不可用", "Gateway path unavailable"),
			lang.pick("网关无法把请求转发到目标设备",
				"the gateway could not forward the request to the target device"), true
	case 0x0B:
		return lang.pick("网关目标设备无响应", "Gateway target device failed to respond"),
			lang.pick("网关后面的目标设备没有回应",
				"the device behind the gateway did not respond"), true
	}
	return "", "", false
}

// field is one row of the byte-by-byte table.
type field struct {
	hex   string
	label string
	desc  string
}

// report accumulates the output sections while a frame is parsed.
type report struct {
	fields []field
	tech   []string
	hints  []string
}

// fieldAt records raw[from:to] as one row of the byte table.
func (r *report) fieldAt(raw []byte, from, to int, label, desc string) {
	r.fields = append(r.fields, field{hex: tools.FormatHex(raw[from:to], " "), label: label, desc: desc})
}

func (r *report) pushTech(s string) { r.tech = append(r.tech, s) }

func (r *report) pushHint(s string) { r.hints = append(r.hints, s) }

// body is the parsed PDU: a one-line summary plus optional per-value rows.
type body struct {
	summary    string
	detailRows []string
	// detailNote is empty when absent. Rust carries Option<String> but never
	// produces an empty note.
	detailNote string
}

type trailerKind int

const (
	trailerTCP trailerKind = iota
	trailerRTU
	trailerASCII
)

// trailer carries the transport's checksum bytes and, for TCP, anything that
// followed the declared length.
type trailer struct {
	kind  trailerKind
	extra []byte // TCP only, nil when the frame holds exactly one PDU
	pass  bool   // RTU only
	lo    byte   // RTU only: expected CRC low byte
	hi    byte   // RTU only: expected CRC high byte
	crc   uint16
	lrc   byte
}

type transportResult struct {
	raw     []byte
	pduOff  int
	pduEnd  int
	unit    byte
	trailer trailer
}

func u16BE(b []byte, i int) uint16 {
	return uint16(b[i])<<8 | uint16(b[i+1])
}

func plcLabel(base uint32, addr uint16) string {
	return fmt.Sprintf("%05d", base+uint32(addr)+1)
}

func unitWord(unit byte, lang Lang) string {
	if unit == 0 {
		return lang.pick("0 号从站（广播）", "slave 0 (broadcast)")
	}
	return lang.pick(fmt.Sprintf("%d 号从站", unit), fmt.Sprintf("slave %d", unit))
}

func quoted(name string, lang Lang) string {
	return lang.pick(fmt.Sprintf("「%s」", name), fmt.Sprintf(`"%s"`, name))
}

func qtyUnit(info fcInfo, qty int, lang Lang) string {
	if lang == Zh {
		return fmt.Sprintf("%d 个%s", qty, info.unitZh)
	}
	word := info.unitEnPlu
	if qty == 1 {
		word = info.unitEn
	}
	return fmt.Sprintf("%d %s", qty, word)
}

// displayWidth counts wide characters as two cells, which is how the byte
// table aligns its columns.
func displayWidth(s string) int {
	width := 0
	for _, r := range s {
		if r >= 0x2E80 {
			width += 2
		} else {
			width++
		}
	}
	return width
}

func pad(s string, w int) string {
	d := displayWidth(s)
	if d >= w {
		return s
	}
	return s + strings.Repeat(" ", w-d)
}

func usableLen(byteCount, payloadLen int) int {
	if byteCount < payloadLen {
		return byteCount
	}
	return payloadLen
}

// Explain parses one frame and renders it. transport is auto / tcp / rtu /
// ascii and direction is auto / request / response.
func Explain(data, transport, direction string, lang Lang) (string, error) {
	if direction != "auto" && direction != "request" && direction != "response" {
		return "", errors.New(lang.pick(
			fmt.Sprintf("方向参数无效：%s（可选 auto / request / response）", direction),
			fmt.Sprintf("Invalid direction: %s (use auto, request or response)", direction)))
	}

	var rep report
	tr, err := parseTransport(data, transport, lang, &rep)
	if err != nil {
		return "", err
	}
	pdu := tr.raw[tr.pduOff:tr.pduEnd]
	if len(pdu) == 0 {
		return "", errors.New(lang.pick(
			"报文里没有 PDU（缺少功能码）",
			"The frame contains no PDU (missing function code)"))
	}
	fcByte := pdu[0]
	isException := fcByte&0x80 != 0
	fc := fcByte & 0x7F
	pduBody := pdu[1:]
	bodyOff := tr.pduOff + 1
	unit := tr.unit
	uw := unitWord(unit, lang)

	info, known := fcInfoFor(fc)
	fcDisplay := lang.pick(info.zh, info.en)
	if !known {
		fcDisplay = lang.pick(fmt.Sprintf("功能码 0x%02X", fc), fmt.Sprintf("function 0x%02X", fc))
	}
	fcQuoted := quoted(fcDisplay, lang)

	isResponse := isException
	if !isException {
		switch direction {
		case "request":
		case "response":
			isResponse = true
		default:
			resp, note := guessDirection(fc, pduBody, lang)
			if note != "" {
				rep.pushHint(note)
			}
			isResponse = resp
		}
	}

	fcLabel := lang.pick("功能码", "Function code")
	switch {
	case isException:
		rep.fieldAt(tr.raw, tr.pduOff, tr.pduOff+1, fcLabel, lang.pick(
			fmt.Sprintf("0x%02X = 0x%02X + 0x80，表示%s出了异常", fcByte, fc, fcQuoted),
			fmt.Sprintf("0x%02X = 0x%02X + 0x80, meaning %s raised an exception", fcByte, fc, fcQuoted)))
		rep.pushTech(lang.pick(
			fmt.Sprintf("功能码: 0x%02X（0x%02X | 0x80，异常响应）", fcByte, fc),
			fmt.Sprintf("Function: 0x%02X (0x%02X | 0x80, exception response)", fcByte, fc)))
	case known:
		rep.fieldAt(tr.raw, tr.pduOff, tr.pduOff+1, fcLabel, lang.pick(
			fmt.Sprintf("0x%02X = %s（%s）", fcByte, info.zh, info.en),
			fmt.Sprintf("0x%02X = %s", fcByte, info.en)))
		rep.pushTech(lang.pick(
			fmt.Sprintf("功能码: 0x%02X（%s / %s）", fcByte, info.en, info.zh),
			fmt.Sprintf("Function: 0x%02X (%s)", fcByte, info.en)))
	default:
		rep.fieldAt(tr.raw, tr.pduOff, tr.pduOff+1, fcLabel, lang.pick(
			fmt.Sprintf("0x%02X，暂不支持详细解析", fcByte),
			fmt.Sprintf("0x%02X; detailed parsing not supported yet", fcByte)))
		rep.pushTech(lang.pick(
			fmt.Sprintf("功能码: 0x%02X", fcByte),
			fmt.Sprintf("Function: 0x%02X", fcByte)))
	}

	var parsed body
	switch {
	case isException:
		parsed = parseExceptionBody(pduBody, tr.raw, bodyOff, fcQuoted, uw, lang, &rep)
	case !known:
		parsed = parseUnknownBody(pduBody, tr.raw, bodyOff, fcQuoted, uw, isResponse, lang, &rep)
	case info.kind == kindBits || info.kind == kindRegs:
		parsed = parseReadBody(info, fcQuoted, pduBody, isResponse, unit, tr.raw, bodyOff, lang, &rep)
	case info.kind == kindWriteSingleCoil || info.kind == kindWriteSingleReg:
		parsed = parseWriteSingleBody(info, fcQuoted, pduBody, isResponse, unit, tr.raw, bodyOff, lang, &rep)
	default:
		parsed = parseWriteMultiBody(info, fcQuoted, pduBody, isResponse, unit, tr.raw, bodyOff, lang, &rep)
	}

	switch tr.trailer.kind {
	case trailerTCP:
		if tr.trailer.extra != nil {
			rep.fields = append(rep.fields, field{
				hex:   tools.FormatHex(tr.trailer.extra, " "),
				label: lang.pick("多余字节", "Extra bytes"),
				desc: lang.pick("超出长度字段声明的部分，可能是下一条报文的开头",
					"bytes beyond the declared length, possibly the start of the next frame")})
		}
	case trailerRTU:
		n := len(tr.raw)
		trText := lang.pick("CRC16 校验通过", "CRC16 check passed")
		if !tr.trailer.pass {
			trText = lang.pick(
				fmt.Sprintf("校验失败，按数据算出应为 %02X %02X", tr.trailer.lo, tr.trailer.hi),
				fmt.Sprintf("check failed; the data computes to %02X %02X", tr.trailer.lo, tr.trailer.hi))
		}
		rep.fieldAt(tr.raw, n-2, n, lang.pick("CRC 校验", "CRC check"), trText)
		rep.pushTech(lang.pick(
			fmt.Sprintf("CRC16: 0x%04X（线上字节序 %02X %02X，%s）", tr.trailer.crc, tr.trailer.lo,
				tr.trailer.hi, crcWord(tr.trailer.pass, lang)),
			fmt.Sprintf("CRC16: 0x%04X (wire order %02X %02X, %s)", tr.trailer.crc, tr.trailer.lo,
				tr.trailer.hi, crcWord(tr.trailer.pass, lang))))
	case trailerASCII:
		n := len(tr.raw)
		rep.fieldAt(tr.raw, n-1, n, lang.pick("LRC 校验", "LRC check"),
			lang.pick("LRC 校验通过", "LRC check passed"))
		rep.pushTech(lang.pick(
			fmt.Sprintf("LRC: 0x%02X（校验通过）", tr.trailer.lrc),
			fmt.Sprintf("LRC: 0x%02X (passed)", tr.trailer.lrc)))
	}
	rep.pushTech(fmt.Sprintf("PDU: %s", tools.FormatHex(pdu, " ")))

	return render(parsed, rep.fields, rep.hints, rep.tech, lang), nil
}

func crcWord(pass bool, lang Lang) string {
	if pass {
		return lang.pick("校验通过", "passed")
	}
	return lang.pick("校验失败", "failed")
}

func parseExceptionBody(pduBody, raw []byte, bodyOff int, fcQuoted, uw string, lang Lang, rep *report) body {
	if len(pduBody) == 0 {
		rep.pushHint(lang.pick(
			"异常响应缺少异常码字节",
			"The exception response is missing the exception code byte"))
		return body{summary: lang.pick(
			fmt.Sprintf("%s拒绝了%s请求，但异常码缺失", uw, fcQuoted),
			fmt.Sprintf("%s rejected the %s request, but the exception code is missing", uw, fcQuoted))}
	}

	code := pduBody[0]
	name, desc, known := exceptionInfo(code, lang)
	if known {
		rep.fieldAt(raw, bodyOff, bodyOff+1, lang.pick("异常码", "Exception code"), lang.pick(
			fmt.Sprintf("0x%02X = %s —— %s", code, name, desc),
			fmt.Sprintf("0x%02X = %s — %s", code, name, desc)))
		rep.pushTech(lang.pick(
			fmt.Sprintf("异常码: 0x%02X（%s）", code, name),
			fmt.Sprintf("Exception code: 0x%02X (%s)", code, name)))
	} else {
		rep.fieldAt(raw, bodyOff, bodyOff+1, lang.pick("异常码", "Exception code"), lang.pick(
			fmt.Sprintf("0x%02X，未知异常码", code),
			fmt.Sprintf("0x%02X, unknown exception code", code)))
		rep.pushTech(lang.pick(
			fmt.Sprintf("异常码: 0x%02X", code),
			fmt.Sprintf("Exception code: 0x%02X", code)))
	}
	if len(pduBody) > 1 {
		rep.pushHint(lang.pick(
			fmt.Sprintf("异常响应通常只带 1 个异常码字节，后面多出 %d 个字节，请留意", len(pduBody)-1),
			fmt.Sprintf("An exception response usually carries exactly 1 exception-code byte; %d extra byte(s) follow", len(pduBody)-1)))
	}
	summary := lang.pick(
		fmt.Sprintf("%s拒绝了%s请求：未知异常码 0x%02X", uw, fcQuoted, code),
		fmt.Sprintf("%s rejected the %s request: unknown exception code 0x%02X", uw, fcQuoted, code))
	if known {
		summary = lang.pick(
			fmt.Sprintf("%s拒绝了%s请求：%s —— %s", uw, fcQuoted, name, desc),
			fmt.Sprintf("%s rejected the %s request: %s — %s", uw, fcQuoted, name, desc))
	}
	return body{summary: summary}
}

func parseUnknownBody(pduBody, raw []byte, bodyOff int, fcQuoted, uw string, isResponse bool, lang Lang, rep *report) body {
	if len(pduBody) > 0 {
		rep.fieldAt(raw, bodyOff, bodyOff+len(pduBody), lang.pick("数据区", "Data area"), lang.pick(
			fmt.Sprintf("共 %d 字节，该功能码暂不支持详细解析", len(pduBody)),
			fmt.Sprintf("%d bytes; detailed parsing not supported for this function yet", len(pduBody))))
		rep.pushTech(lang.pick(
			fmt.Sprintf("数据: %s", tools.FormatHex(pduBody, " ")),
			fmt.Sprintf("Data: %s", tools.FormatHex(pduBody, " "))))
	}
	head := lang.pick(
		fmt.Sprintf("主站发给 %s 的%s", uw, fcQuoted),
		fmt.Sprintf("%s from the master to %s", fcQuoted, uw))
	if isResponse {
		head = lang.pick(
			fmt.Sprintf("%s回复的%s", uw, fcQuoted),
			fmt.Sprintf("%s replied by %s", fcQuoted, uw))
	}
	return body{summary: lang.pick(
		fmt.Sprintf("%s：暂不支持详细解析，仅展示基本结构", head),
		fmt.Sprintf("%s: detailed parsing not supported yet; showing the basic structure only", head))}
}

func render(parsed body, fields []field, hints, tech []string, lang Lang) string {
	var out strings.Builder
	out.WriteString(parsed.summary)
	section := func(title string) string { return fmt.Sprintf("\n\n── %s ──\n", title) }

	// Rust drops the block's trailing newline with out.pop(); joining the rows
	// instead of terminating each one produces the same bytes.
	if len(parsed.detailRows) > 0 {
		out.WriteString(section(lang.pick("数据明细", "Data details")))
		out.WriteString(strings.Join(parsed.detailRows, "\n"))
		if parsed.detailNote != "" {
			out.WriteString("\n")
			out.WriteString(parsed.detailNote)
		}
	}

	out.WriteString(section(lang.pick("逐字节对照", "Byte-by-byte")))
	w1, w2 := 0, 0
	for _, f := range fields {
		if w := displayWidth(f.hex); w > w1 {
			w1 = w
		}
		if w := displayWidth(f.label); w > w2 {
			w2 = w
		}
	}
	rows := make([]string, 0, len(fields))
	for _, f := range fields {
		rows = append(rows, fmt.Sprintf("%s  %s  %s", pad(f.hex, w1), pad(f.label, w2), f.desc))
	}
	out.WriteString(strings.Join(rows, "\n"))

	if len(hints) > 0 {
		out.WriteString(section(lang.pick("提示", "Notes")))
		out.WriteString(strings.Join(hints, "\n"))
	}

	out.WriteString(section(lang.pick("技术细节", "Technical details")))
	out.WriteString(strings.Join(tech, "\n"))
	return out.String()
}
